// 阶段4课程数据（第40-52周），由 H5 版自动提取
module.exports = [{"w":40,"p":4,"theme":"听力专项一：基础题型","d":[{"t":"数字、时间与拼写","obj":"攻克听力第一关：数字与字母反应速度","time":"45分钟","v":[{"w":"double","m":"双的；两个的","p":"adj.","e":"My number is five double two, four."},{"w":"quarter","m":"四分之一；一刻钟","p":"n.","e":"The meeting starts at a quarter past nine."},{"w":"fortnight","m":"两星期","p":"n.","e":"The reservation is for a fortnight."},{"w":"noon","m":"正午","p":"n.","e":"The flight leaves at noon sharp."},{"w":"available","m":"可用的；有空的","p":"adj.","e":"Is Friday morning available?"}],"g":{"t":"数字听写要领","exp":"13与30、15与50靠结尾区分：thirTEEN重音在后，THIRty重音在前。电话号码里8读double eight，0可读oh/zero/nought。日期读法：May the third或the third of May。这些反应必须练到不假思索。","ex":["thirteen vs thirty","fifteen vs fifty","double six, zero four"]},"pr":"1) 找数字听写音频（可用真题Section 1），写20组数字/时间/电话。2) 自己录10组数字（手机念中文随机数），翻译成英文再听写。3) 口头快速读出：13/30/14/40/15/50/16/60。","tip":"听力丢分的第一大坑就是数字。每天5分钟数字听写，两周后你会回来感谢今天的自己。"},{"t":"租房场景与表格填空","obj":"掌握最高频Section 1场景，学会表格填空","time":"45分钟","v":[{"w":"landlord","m":"房东","p":"n.","e":"The landlord lives downstairs."},{"w":"tenant","m":"租客","p":"n.","e":"The tenant pays rent monthly."},{"w":"deposit","m":"押金；定金","p":"n.","e":"A deposit of 500 dollars is required."},{"w":"furniture","m":"家具","p":"n.","e":"The flat comes with furniture."},{"w":"suburb","m":"郊区","p":"n.","e":"They live in a quiet suburb."}],"g":{"t":"表格填空题（Form Completion）","exp":"读题时间干三件事：1) 看表格标题知道场景；2) 判断每个空的词性（数字？名词？）；3) 看清字数限制 NO MORE THAN THREE WORDS。填答案时：单复数跟录音，人名地名首字母大写。","ex":["Rent: 450 dollars per month","Address: 21 Green Street","Date available: 5th March"]},"pr":"1) 背熟租房场景词（本日5词+rent/contract/bill）。2) 做一套租房类Section 1填空题。3) 把错题按词性/拼写/没听到三类归因。","tip":"Section 1填空是听力最简单的10分，中国考生往往错在拼写和单复数——纯手熟，别丢冤分。"},{"t":"选择题攻略","obj":"学会读题预测与排除干扰项","time":"45分钟","v":[{"w":"majority","m":"大多数","p":"n.","e":"The majority agreed with the plan."},{"w":"option","m":"选项","p":"n.","e":"Read all the options before choosing."},{"w":"statement","m":"陈述；说法","p":"n.","e":"Which statement is correct?"},{"w":"prefer","m":"更喜欢","p":"v.","e":"She prefers the morning class."},{"w":"postpone","m":"推迟","p":"v.","e":"They postponed the meeting to Friday."}],"g":{"t":"选择题三步法","exp":"第一步：读题干圈关键词（谁？做什么？）。第二步：扫选项找差异点。第三步：听时盯住转折词——but/however/actually之后才是真答案，前面提到的常是干扰项。先听到的不一定是答案。","ex":["I wanted to join the gym... but actually I chose the swimming class.","The course was postponed to Friday.","Actually, the majority changed their minds."]},"pr":"1) 做一套单选题（10题），先写预测再听。2) 统计：正确答案出现在but/however之后的有几题。3) 用prefer/majority各造2句。","tip":"选择题的陷阱设计模式固定：先给一个似是而非的选项，再转折给真答案。听到but要竖起耳朵，这是出题人的暗号。"},{"t":"同义替换识别","obj":"掌握雅思听力的核心机制","time":"45分钟","v":[{"w":"purchase","m":"购买","p":"v./n.","e":"You can purchase tickets online."},{"w":"assist","m":"帮助","p":"v.","e":"The staff will assist you."},{"w":"notify","m":"通知","p":"v.","e":"Please notify us of any changes."},{"w":"cancel","m":"取消","p":"v.","e":"They cancelled the event."},{"w":"requirement","m":"要求","p":"n.","e":"Check the entry requirements first."}],"g":{"t":"同义替换（Paraphrasing）","exp":"雅思听力所有题目的题干都和录音原文不同词：题目写buying，录音说purchase；题目写help，录音说assist。这叫同义替换。技巧：读题时给每个关键词默想2-3个同义词，听的时候就是在'等'这些替换词出现。","ex":["buy = purchase = pay for","help = assist = give a hand","tell = notify = inform"]},"pr":"1) 把今天5个词各写出2个同义表达。2) 做一套填空+选择混合题，划出每道题的替换对。3) 自建'替换对'笔记本，今天记10对。","tip":"能不能听懂替换，决定听力5分和6.5分的差距。从今天起每套题都收集替换对，四周后你会拥有自己的'题库透视镜'。"},{"t":"地图题与方位词","obj":"攻克配对地图题，练方位反应速度","time":"45分钟","v":[{"w":"opposite","m":"在对面","p":"prep.","e":"The bank is opposite the post office."},{"w":"adjacent","m":"相邻的","p":"adj.","e":"The cafe is adjacent to the library."},{"w":"intersection","m":"十字路口","p":"n.","e":"Turn left at the intersection."},{"w":"corridor","m":"走廊","p":"n.","e":"The office is at the end of the corridor."},{"w":"entrance","m":"入口","p":"n.","e":"Meet me at the main entrance."}],"g":{"t":"地图题四步走","exp":"1) 看指南针和起点（You are here）；2) 题目念方位时手里转笔跟着走（把自己当主角）；3) 熟悉三大陷阱：先说错再改口（actually再往左）、用参照物（next to/opposite）不总说左右；4) 顺序原则：第1题在录音前段，别恋战。","ex":["Go straight until you reach the intersection.","It's on your right, opposite the gift shop.","The entrance is just past the corridor."]},"pr":"1) 背熟方位词表（本日5词+go straight/turn left/at the corner）。2) 做一套地图题。3) 拿自己家或学校画一张简图，用英文录音描述3个地点位置。","tip":"地图题是中国考生的传统弱项，但其实是套路最固定的题型。方位词反应速度练上去，它反而变成送分题。"}],"sun":{"t":"第40周自检：听力基础题型","obj":"检验数字、填空、选择、地图四大基础题型","pr":"1) 完成一套完整Section 1+2（约20分钟，严格计时）。2) 对答案后做错题归因表：数字错？拼写错？替换没听出？3) 把本周5词+全部场景词听写一遍。4) 错题精听：逐句听懂为止。","tip":"从这周起进入冲刺节奏：每套听力题都要'限时做+精听错'两遍走，只做不改等于白做。"}},{"w":41,"p":4,"theme":"听力专项二：校园与学术场景","d":[{"t":"校园服务场景","obj":"掌握Section 2介绍类独白","time":"45分钟","v":[{"w":"enrollment","m":"注册；登记","p":"n.","e":"Enrollment starts next Monday."},{"w":"registration","m":"注册（手续）","p":"n.","e":"Complete the online registration first."},{"w":"campus","m":"校园","p":"n.","e":"The campus has two libraries."},{"w":"facility","m":"设施","p":"n.","e":"The sports facilities are free for students."},{"w":"certificate","m":"证书","p":"n.","e":"You will receive a certificate at the end."}],"g":{"t":"Section 2 独白攻略","exp":"Section 2是一个人介绍（设施/活动/参观路线），语速中等。诀窍：1) 开头必说'今天讲什么'，听懂总览就赢一半；2) 例子出现处后面常跟答案；3) 讲解人会重复强调重点（The important thing is... / Remember...）。","ex":["Today I'd like to tell you about our new facilities.","The important thing to remember is that enrollment closes on Friday.","For example, the gym opens at six in the morning."]},"pr":"1) 做一套Section 2。2) 把录音里所有'强调信号'（important/remember/don't forget）划出来，看后面是不是答案。3) 用facility/campus写5句自己学校介绍。","tip":"Section 2的独白结构感很强：总-分-总。抓住开头和强调句，及格线轻松迈过。"},{"t":"小组讨论（Section 3）","obj":"学会听双人讨论，区分观点归属","time":"45分钟","v":[{"w":"assignment","m":"作业；任务","p":"n.","e":"The assignment is due next week."},{"w":"deadline","m":"截止日期","p":"n.","e":"Don't miss the deadline."},{"w":"draft","m":"草稿","p":"n.","e":"I finished the first draft."},{"w":"feedback","m":"反馈","p":"n.","e":"The tutor gave useful feedback."},{"w":"presentation","m":"演示；报告","p":"n.","e":"We have a presentation on Friday."}],"g":{"t":"Section 3 观点归属","exp":"Section 3是两人（常为师生/同学）讨论作业。最大考点：这句话是谁的观点？抓三样：1) 名字或称谓（the man/the woman/tutor）；2) 观点信号词：agree/disagree/think/suggest；3) 一个同意另一个补充，答案常在补充里。","ex":["The woman suggests changing the topic.","I agree with the tutor about the deadline.","The man thinks the draft needs more data."]},"pr":"1) 做一套Section 3。2) 边听边记：每段话写M/W（男/女），对答案时验证归属。3) 用suggest/agree写6句'转述他人观点'的句子。","tip":"Section 3错10题里有6题是'张冠李戴'。养成笔记标注说话人的习惯，一步到位。"},{"t":"学术讲座（Section 4）","obj":"攻克最难独白：学术笔记填空","time":"45分钟","v":[{"w":"hypothesis","m":"假设","p":"n.","e":"The hypothesis was finally proven."},{"w":"experiment","m":"实验","p":"n.","e":"The experiment lasted three months."},{"w":"survey","m":"调查","p":"n.","e":"The survey covered 500 families."},{"w":"species","m":"物种","p":"n.","e":"This species is endangered."},{"w":"migration","m":"迁徙；迁移","p":"n.","e":"The migration happens every autumn."}],"g":{"t":"Section 4 笔记填空法","exp":"Section 4是学术讲座独白，无对话。策略：1) 开头30秒必听懂主题（决定全篇语境）；2) 跟着讲义大纲走：firstly/next/then/finally是分层信号，每换一层，对应下一题；3) 填空词常是讲座的核心名词，紧跟在解释之后。","ex":["Firstly, let's look at the background of the experiment.","Next, the survey results will surprise you.","Finally, the species completed its migration in two weeks."]},"pr":"1) 做一套Section 4，先只听结构：数一数出现了几个firstly/next/finally。2) 再做一遍填空。3) 用hypothesis/experiment/survey写4句'研究报告'式句子。","tip":"Section 4看着吓人，其实填空词都是'讲座重心词'，会慢、会重读、会重复。别被专业背景吓退，你只需要抓住那几个词。"},{"t":"精听与听写法","obj":"掌握提升听力上限的核心训练法","time":"45分钟","v":[{"w":"transcribe","m":"转录；听写","p":"v.","e":"Transcribe one minute of the audio."},{"w":"imitate","m":"模仿","p":"v.","e":"Imitate the speaker's intonation."},{"w":"chunk","m":"意群；语块","p":"n.","e":"Listen in chunks, not word by word."},{"w":"stress","m":"重音；重读","p":"n./v.","e":"The stress falls on the second syllable."},{"w":"rhythm","m":"节奏","p":"n.","e":"English has a strong rhythm."}],"g":{"t":"精听四步法（每天10分钟）","exp":"选一段30秒真题：1) 盲听两遍，能写多少写多少；2) 对照原文，标出没听出的地方（连读？弱读？生词？）；3) 跟读模仿3遍，模仿到语音语调一样；4) 脱稿再盲听，直到全部听懂。一段材料吃透，胜过泛听一小时。","ex":["Step 1: Blind listen twice.","Step 2: Check the transcript.","Step 3: Shadow and imitate.","Step 4: Blind listen again."]},"pr":"1) 挑一段Section 4做完整精听四步。2) 统计没听出的原因：连读/弱读/生词各占几个。3) 连读最严重的3处反复跟读10遍。","tip":"精听是听力从6到7的唯一窄门。每天雷打不动10分钟，一个月后你会感觉'耳朵突然开了'。"},{"t":"口音适应与猜词","obj":"适应英澳口音，学会靠上下文补漏","time":"45分钟","v":[{"w":"accent","m":"口音","p":"n.","e":"The speaker has an Australian accent."},{"w":"dialect","m":"方言","p":"n.","e":"The dialect is hard to follow."},{"w":"pronounce","m":"发音","p":"v.","e":"How do you pronounce this word?"},{"w":"context","m":"上下文","p":"n.","e":"Guess the meaning from context."},{"w":"fluent","m":"流利的","p":"adj.","e":"She speaks fluent English."}],"g":{"t":"口音应对策略","exp":"雅思主流是英音，也有澳音。应对：1) BBC纪录片+澳洲ABC新闻交替听，各听一周；2) 熟悉英音特点：a读/ɑː/（fast），o读/ɒ/；3) 实在没听清单词：靠语法（单复数、时态）和语境（前后词）推，别卡在一个词上，丢了后面三题。","ex":["British: fast, bath, dance (long a)","Australian: today sounds like to-die","Never freeze on one word - keep moving."]},"pr":"1) 各找3分钟英音/澳音材料盲听，写下大意。2) 对比两种口音听错的词，总结规律。3) 用context写3句：靠上下文猜词的经历。","tip":"考场上没听清的一个词就让它过去。听力是流动的河，别为一朵浪花停下整条船。"}],"sun":{"t":"第41周自检：听力学术场景","obj":"检验Section 2-4与精听效果","pr":"1) 完整做一套Section 3+4（限时）。2) 精听本周两篇最难的段落。3) 听写本周25词+上周25词（滚动）。4) 自评：数字、观点归属、讲座分层三大弱项哪个还没过关？下周前三天再补一次。","tip":"听力是四科里最容易通过'刷+精听'短期提分的。这周结束，你应该能稳定对22+/30了。"}},{"w":42,"p":4,"theme":"阅读专项一：判断与填空","d":[{"t":"判断题：True/False","obj":"掌握题目定位与T/F判断标准","time":"45分钟","v":[{"w":"accurate","m":"准确的","p":"adj.","e":"The report is accurate."},{"w":"claim","m":"声称；主张","p":"v./n.","e":"The author claims otherwise."},{"w":"evidence","m":"证据","p":"n.","e":"There is little evidence for this."},{"w":"consistent","m":"一致的","p":"adj.","e":"The data is consistent with the theory."},{"w":"contradict","m":"与矛盾；反驳","p":"v.","e":"The results contradict the claim."}],"g":{"t":"True/False判断（针对事实）","exp":"T/F题考事实：题目与原文意思一致选T，相反（反义/反向）选F。步骤：1) 圈题目关键词（数字、专有名词优先）；2) 回原文定位那句话；3) 逐词比对方向。注意：同义替换不改意思=T，加了原文没有的信息≠F（可能是NG，明天讲）。","ex":["Original: The bridge was built in 1890. / Statement: The bridge dates from the late 19th century. (TRUE)","Original: Prices fell sharply. / Statement: Prices rose slowly. (FALSE)"]},"pr":"1) 做一组T/F题（8题），先写定位词再做题。2) 每题写出'原文句+判断理由'。3) 用claim/contradict/consistent各造1句学术句。","tip":"判断题的第一技能是'找到那句话'。90%的错误不是判断错，是定位错——题干关键词没圈对。"},{"t":"判断题：Not Given","obj":"攻克阅读最难题：NG的三大特征","time":"45分钟","v":[{"w":"specific","m":"具体的","p":"adj.","e":"Give a specific example."},{"w":"mention","m":"提到","p":"v.","e":"The article mentions two causes."},{"w":"relevant","m":"相关的","p":"adj.","e":"This detail is not relevant."},{"w":"assume","m":"假设；认为","p":"v.","e":"Scientists assume the theory is right."},{"w":"infer","m":"推断","p":"v.","e":"Do not infer too much from the text."}],"g":{"t":"Not Given 三大特征","exp":"选NG的情况：1) 原文根本没提这个信息（关键词找不到）；2) 原文提了但无法证实（He is rich? 原文只说他有工作）；3) 题目比原文具体（原文说some people，题目说most people）。核心心法：你的判断只能基于原文，不许用自己的常识脑补。","ex":["Original: Many tourists visit the castle. / Statement: Most tourists love the castle. (NOT GIVEN)","Original: He works as a teacher. / Statement: He is wealthy. (NOT GIVEN)"]},"pr":"1) 做一组NG专项题（8题），每题标注属于三大特征的哪一类。2) 写3个自己'差点脑补'的例子。3) 复述NG三特征给空气听一遍。","tip":"NG题考的是克制：不知道就是不知道。考生总忍不住用常识补全——雅思要的是'忠实于原文'，不是聪明。"},{"t":"摘要填空题","obj":"掌握Summary Completion技巧","time":"45分钟","v":[{"w":"summary","m":"摘要；总结","p":"n.","e":"Complete the summary below."},{"w":"gap","m":"空格；缺口","p":"n.","e":"Fill in the gaps with one word."},{"w":"synonym","m":"同义词","p":"n.","e":"Find the synonym in the passage."},{"w":"locate","m":"定位；找出","p":"v.","e":"Locate the relevant paragraph."},{"w":"extract","m":"提取；摘录","p":"v.","e":"Extract the exact word from the text."}],"g":{"t":"摘要填空三步法","exp":"1) 先读摘要首句和空格前后，判断词性（名词/动词/形容词）和话题；2) 摘要顺序=原文顺序（基本），从最特殊的词定位回原文；3) 答案词照抄原文原形，注意题目前后要求的词形变化。带选项的版本更考替换识别。","ex":["The ___ of the study surprised everyone. (noun needed)","Researchers ___ three methods. (past verb needed)"]},"pr":"1) 做一篇带摘要填空的文章。2) 每个空标注词性预测，再验证命中率。3) 用locate/extract/synonym写3句'做题流程'描述。","tip":"摘要填空本质是'缩小版的原文'。先判词性再定位，命中率能从一半提到八成——词性就是你的筛选器。"},{"t":"简答与句子完成","obj":"学会按字数限制精准作答","time":"45分钟","v":[{"w":"brief","m":"简短的","p":"adj.","e":"Give a brief answer."},{"w":"respond","m":"回答","p":"v.","e":"Respond with one word only."},{"w":"complete","m":"完成；补全","p":"v.","e":"Complete the sentence below."},{"w":"limit","m":"限制","p":"n./v.","e":"Mind the word limit."},{"w":"original","m":"原来的；原文的","p":"adj.","e":"Use words from the original text."}],"g":{"t":"字数限制军规","exp":"NO MORE THAN THREE WORDS = 最多3词，1词也对；ONE WORD ONLY = 必须1词。军规：1) 冠词a/the算1词；2) 连字符词（well-known）算1词；3) 数字5000算1词；4) 永远照抄原文，不要自己改写答案；5) 大小写按题目格式（句首大写）。每年无数人栽在超字数上。","ex":["Answer within three words: 'increasing air pollution' (3, OK)","Answer within three words: 'the increasing of air pollution' (5, WRONG)"]},"pr":"1) 做一组句子完成题（10题），写完数字数。2) 故意做错3种字数情况，体会红线。3) 用brief/respond/limit写3句考场提醒。","tip":"超字数=0分，再简单的词也算错。写完答案默数一遍单词数，这2秒钟能救一道题。"},{"t":"长难句拆解","obj":"掌握三步拆句法，攻克理解瓶颈","time":"45分钟","v":[{"w":"clause","m":"从句","p":"n.","e":"Identify the main clause first."},{"w":"modify","m":"修饰","p":"v.","e":"Which word does this phrase modify?"},{"w":"identify","m":"识别；确认","p":"v.","e":"Identify the subject and verb."},{"w":"structure","m":"结构","p":"n.","e":"The structure is complex but clear."},{"w":"simplify","m":"简化","p":"v.","e":"Simplify the sentence in your mind."}],"g":{"t":"长难句三步拆解法","exp":"第一步：找主干——主语+谓语+宾语（谁是主角？干了什么？）。第二步：剥离从句——which/that/who引导的先括起来不看。第三步：修饰归位——形容词、介词短语回到它修饰的词旁边。例：The theory [that most scientists now accept] was proposed in 1970. 主干=The theory was proposed in 1970. 一秒看懂。","ex":["The survey (which was conducted in 2015) covered 2,000 households.","What surprised the researchers was the speed of the change."]},"pr":"1) 从真题里挑5个长难句，用'主干+括号剥离法'手写拆解。2) 把每句缩成10词以内的'骨架句'。3) 用identify/simplify造2句学习方法描述。","tip":"长难句不是词难，是'套娃'多。先抓主干再看装饰，这个习惯会让你阅读速度快一倍。"}],"sun":{"t":"第42周自检：阅读基础题型","obj":"检验T/F/NG、填空、长难句","pr":"1) 限时20分钟做一篇真题文章（含判断+填空）。2) 错题归因：定位错/替换没认出/理解错/字数超，各几题？3) 听写本周25词。4) 重做本周最难的一个长难句，10秒内说出主干。","tip":"阅读提分公式：定位准+替换熟+不脑补。三项都有了，一篇13题对10题不是梦。"}},{"w":43,"p":4,"theme":"阅读专项二：匹配与速度","d":[{"t":"标题匹配题","obj":"攻克List of Headings","time":"45分钟","v":[{"w":"heading","m":"标题","p":"n.","e":"Choose the best heading for each paragraph."},{"w":"paragraph","m":"段落","p":"n.","e":"Read the first two sentences of each paragraph."},{"w":"capture","m":"捕捉；抓住","p":"v.","e":"The heading captures the main idea."},{"w":"misleading","m":"误导性的","p":"adj.","e":"Some headings are deliberately misleading."},{"w":"detail","m":"细节","p":"n.","e":"A heading is never about a small detail."}],"g":{"t":"标题匹配法","exp":"段落主旨藏在：首句、第二句、转折句（but/however后）、末句。策略：1) 先读段落再回选项，别被选项先入为主；2) 干扰项特征=段落里某个细节词（以偏概全）或段落没展开的例子；3) NB：有的选项是例子/干扰，多出的选项不用；4) 做完把标题连起来读，应该是一篇'文章大纲'。","ex":["Paragraph: 'But the new study changed everything...' (focus after 'But')","A heading with only one paragraph-specific word is often a trap."]},"pr":"1) 做一篇含标题匹配的文章（8个段落）。2) 每段用铅笔划出'主旨句'再选标题。3) 对照分析：选错的标题是'细节陷阱'还是'未展开'？","tip":"标题匹配错，多半是被'段落里出现过的词'骗了。记住：出现过的词不一定是主旨，全段都在讲的才是。"},{"t":"段落信息匹配","obj":"攻克Which paragraph contains题型","time":"45分钟","v":[{"w":"contain","m":"包含","p":"v.","e":"Which paragraph contains this information?"},{"w":"description","m":"描述","p":"n.","e":"Find the description of the process."},{"w":"reference","m":"提及；参考","p":"n.","e":"There is a reference to early attempts."},{"w":"explanation","m":"解释","p":"n.","e":"The explanation appears in paragraph C."},{"w":"unique","m":"独特的","p":"adj.","e":"Find the unique keyword in each question."}],"g":{"t":"段落信息匹配策略","exp":"题目给信息点，你找它在哪个段落。特点：乱序！且可能一段出两题。策略：1) 每题圈'特征词'（数字、专有名词、独特名词）；2) 拿着特征词扫读全篇定位；3) 简单题（含数字）先做，难题后做；4) 一段被用过两次就划掉，缩小剩余范围。","ex":["Question: a reference to a failed attempt -> scan for 'fail/unsuccessful/attempt'","Question: the year when the factory closed -> scan for years (1865? 1902?)"]},"pr":"1) 做一篇段落信息匹配（7题）。2) 记录做题顺序：先做了哪几题？为什么？3) 用contain/reference/explanation造3句题目描述。","tip":"这题型乱序，逼你全篇扫。特征词找得准，扫一遍就出来；找不准，五遍都白扫——特征词优先级：数字>专有名词>独特名词。"},{"t":"人名观点匹配","obj":"攻克Matching Features（人名/理论）","time":"45分钟","v":[{"w":"researcher","m":"研究者","p":"n.","e":"Which researcher made this claim?"},{"w":"theory","m":"理论","p":"n.","e":"Each theory has its supporters."},{"w":"argue","m":"主张；争辩","p":"v.","e":"She argues that the data is flawed."},{"w":"discover","m":"发现","p":"v.","e":"The team discovered a new species."},{"w":"attribute","m":"把归于","p":"v.","e":"He attributes the change to pollution."}],"g":{"t":"人名配观点三步","exp":"1) 先把所有人名圈出来（大写字母，好定位），标上A/B/C；2) 逐个人名回原文，读其前后观点句（常为argue/claim/suggest/believe/point out后的宾语从句）；3) 观点常被同义替换（原文discover，题目find out）。一个人名可能用两次，注意NB提示。","ex":["Dr. Lee argues that sleep affects memory.","The theory proposed by Brown was later challenged.","Which researcher attributes the decline to climate?"]},"pr":"1) 做一篇人名观点匹配（5题）。2) 列表：人名-原文观点-题目替换词。3) 用argue/attribute/claim各造1句转述句。","tip":"人名题是匹配题里的'送分题'：名字好找、观点就一句。把它练成必得分，给难题留时间。"},{"t":"扫读与略读","obj":"掌握skimming与scanning双技术","time":"45分钟","v":[{"w":"scan","m":"扫读（找特定信息）","p":"v.","e":"Scan the text for the year 1930."},{"w":"skim","m":"略读（抓大意）","p":"v.","e":"Skim the first paragraph quickly."},{"w":"keyword","m":"关键词","p":"n.","e":"Circle the keywords in the question."},{"w":"rapidly","m":"迅速地","p":"adv.","e":"Move your eyes rapidly across lines."},{"w":"ignore","m":"忽略","p":"v.","e":"Ignore unknown words while scanning."}],"g":{"t":"略读 vs 扫读","exp":"Skimming（略读）：3分钟读完一篇文章，只看标题+首末句+每段首句，目的是知道'文章讲什么、结构什么样'。Scanning（扫读）：眼睛像雷达一样找特定词（数字/大写/专有名词），其余全忽略，目的是'定位'。做题=先skim建地图，再scan找坐标。","ex":["Skim: 'This article discusses... In conclusion, ...'","Scan: Find '1985' among 700 words in 10 seconds."]},"pr":"1) 拿一篇真题：3分钟skim后合上书，口头说文章主旨和结构。2) 再用scan找10个指定词，计时。3) 用ignore/rapidly写3句阅读技巧句。","tip":"普通考生逐字读，高分考生'跳跃读'。眼睛的移动方式决定了60分钟内你能做完几篇——这是体力活也是技术活。"},{"t":"三篇60分钟时间管理","obj":"建立考场时间分配系统","time":"45分钟","v":[{"w":"allocate","m":"分配","p":"v.","e":"Allocate 20 minutes to each passage."},{"w":"pace","m":"节奏","p":"n.","e":"Keep a steady pace."},{"w":"budget","m":"预算；安排","p":"n./v.","e":"Budget your time wisely."},{"w":"prioritize","m":"优先处理","p":"v.","e":"Prioritize easy questions first."},{"w":"flexible","m":"灵活的","p":"adj.","e":"Be flexible when a question blocks you."}],"g":{"t":"20-20-20时间法","exp":"每篇20分钟：3分钟skim+15分钟做题+2分钟誊写检查。铁律：1) 一道题卡超过90秒，标记跳过（做个记号），全篇做完回来再看；2) 匹配题耗时，放一篇中间做；3) 最后必须留2分钟：检查有没有漏涂、字数有没有超。放弃一道难题，救活两道简单题。","ex":["Passage 1: easiest - go fast, bank time","A question stuck for 90 seconds? Mark and move.","Always keep the last 2 minutes for checking."]},"pr":"1) 完整做3篇（严格60分钟）。2) 记录每篇实际用时。3) 复盘：超时的那篇，时间漏在哪种题型上？4) 制定自己的'跳题规则'写在错题本首页。","tip":"考场上最大的敌人是'一道题恋战'。练习时就建立'90秒就撤'的条件反射，这是纪律，不是天赋。"}],"sun":{"t":"第43周自检：阅读全套模考","obj":"检验匹配题型与60分钟时间管理","pr":"1) 完整模考3篇60分钟（严格计时）。2) 统计各题型正确率：判断/填空/标题/段落信息/人名。3) 听写本周25词。4) 写'我的时间分配表'：哪篇先做、哪种题型先跳。","tip":"阅读六分=对27/40，七分=对30/40。模考稳定28+，你就安全了；还差2题？下周的精析日找它们。"}},{"w":44,"p":4,"theme":"写作专项一：Task 1 图表作文","d":[{"t":"线图词汇","obj":"掌握趋势动词三档库","time":"45分钟","v":[{"w":"increase","m":"上升","p":"v./n.","e":"Sales increased steadily."},{"w":"decline","m":"下降","p":"v./n.","e":"The number declined gradually."},{"w":"fluctuate","m":"波动","p":"v.","e":"Prices fluctuated between 2000 and 2010."},{"w":"peak","m":"达到顶峰","p":"v./n.","e":"Revenue peaked in 2015."},{"w":"stabilize","m":"趋于稳定","p":"v.","e":"The figures stabilized at around 40%."}],"g":{"t":"趋势动词三档库","exp":"上升三档：rise（升）→ climb（稳步升）→ soar/surge（飙升）；下降三档：fall → drop → plunge（暴跌）；平稳：remain stable / level off；波动：fluctuate。副词三档：slightly < steadily < dramatically。组合使用：climbed steadily / plunged dramatically。","ex":["The price of gold soared dramatically in 2011.","Visitors fell slightly before stabilizing at 2 million.","Costs fluctuated wildly throughout the decade."]},"pr":"1) 画一条自己编的曲线（10个数据点），用8个不同'动词+副词'组合描述它。2) 背诵三档词库，默写一遍。3) 用fluctuate/peak/stabilize各造1句。","tip":"Task 1的语言分就藏在这三档词里。全文只用rise和fall，词汇分直接5.5；会用soar/plunge/level off，6分稳了。"},{"t":"柱图与饼图","obj":"掌握比例与比较表达","time":"45分钟","v":[{"w":"proportion","m":"比例","p":"n.","e":"The proportion of students rose to 60%."},{"w":"majority","m":"大多数","p":"n.","e":"A majority of respondents agreed."},{"w":"category","m":"类别","p":"n.","e":"Food was the largest category."},{"w":"compare","m":"比较","p":"v.","e":"Compare the two charts."},{"w":"respectively","m":"分别地","p":"adv.","e":"France and Germany scored 20% and 15% respectively."}],"g":{"t":"柱图与饼图描述法","exp":"柱图：抓最值（the highest/lowest）、抓对比（whereas/while）、抓倍数。饼图：占比说法（accounted for 30% / made up a quarter / represented half）；最大块开刀，最小块收尾。respectively连写两个数据，是高档句式的代表。","ex":["Food accounted for the largest proportion, at 35%.","France and Germany spent 20% and 15% respectively.","Men preferred sports, whereas women favored reading."]},"pr":"1) 找一个柱图+一个饼图，各写6句描述（不用成文）。2) 强制使用：account for / whereas / respectively 各至少1次。3) 用proportion/category造2句。","tip":"图表作文不是'报数字'，是'讲故事'：最大最小、此消彼长。考官想看你抓重点的眼睛，不是计算器。"},{"t":"表格与流程图","obj":"掌握表格对比与流程被动语态","time":"45分钟","v":[{"w":"figure","m":"数字；数据","p":"n.","e":"The figures show a clear trend."},{"w":"stage","m":"阶段","p":"n.","e":"The process has five stages."},{"w":"raw","m":"生的；未加工的","p":"adj.","e":"Raw materials are delivered first."},{"w":"process","m":"过程；加工","p":"n./v.","e":"The beans are processed in factories."},{"w":"manufacture","m":"制造","p":"v.","e":"The goods are manufactured locally."}],"g":{"t":"表格抓最值 & 流程图被动化","exp":"表格题：数据多别慌，只抓三样——最大、最小、最反常。'横着比、竖着比'各写两句即可。流程图：全程被动语态（The beans are washed / are dried / are packed），按箭头顺序，每步一个谓语，用next/then/subsequently串联。别加观点，流程图没有overview趋势，可写'共几步、起止点'。","ex":["The raw materials are first washed, then dried in the sun.","The figure for Japan was the highest in every column.","Once packaged, the product is shipped to retailers."]},"pr":"1) 找一个表格，写4句'最值+对比'。2) 找一个流程图，写6步被动句。3) 用stage/manufacture/process各造1句。","tip":"流程图万年被动语态。看到'某物被如何处理'，are/is + 过去分词直接上，一句主动语态都别写。"},{"t":"Task 1 结构模板","obj":"掌握四段式与Overview写法","time":"45分钟","v":[{"w":"overview","m":"总览（必须段）","p":"n.","e":"The overview summarizes the main trend."},{"w":"overall","m":"总体而言","p":"adv.","e":"Overall, consumption rose in all groups."},{"w":"trend","m":"趋势","p":"n.","e":"The trend continued until 2010."},{"w":"significant","m":"显著的","p":"adj.","e":"There was a significant change."},{"w":"whereas","m":"然而；反之","p":"conj.","e":"Sales rose in Asia, whereas they fell in Europe."}],"g":{"t":"Task 1 四段结构","exp":"第一段Introduction：改写题目（换词换句式，不抄原题）。第二段Overview：2句话概括最显著特征（整体升/降？谁最大谁最小？）——这是band 6与7的分水岭，没有overview封顶5分！第三段Detail 1：描述前半段/一组数据。第四段Detail 2：描述后半段/另一组。数据分组：时间轴砍一半、或类别分两堆。","ex":["Introduction: The line graph illustrates how... changed over...","Overview: Overall, the number of visitors increased substantially, although the growth slowed after 2010.","Detail 2: In contrast, figures for Europe remained stable."]},"pr":"1) 背熟四段框架图（口述一遍）。2) 给一个图表写Overview 2句（不许报具体数字！）。3) 用whereas/overall写3句概括句。","tip":"Overview是考官扫一眼定档的地方：'总体什么趋势、谁最大'两句话，不写具体数字。记住：先给结论，再给证据。"},{"t":"数据描述句型","obj":"掌握约数、倍数、比较句型","time":"45分钟","v":[{"w":"approximately","m":"大约","p":"adv.","e":"The figure stood at approximately 50%."},{"w":"roughly","m":"大致","p":"adv.","e":"Roughly one third chose option A."},{"w":"nearly","m":"接近","p":"adv.","e":"Sales reached nearly 2 million."},{"w":"twice","m":"两倍","p":"adv./n.","e":"Exports were twice the level of imports."},{"w":"threefold","m":"三倍（的）","p":"adj./adv.","e":"There was a threefold increase."}],"g":{"t":"约数与倍数句型","exp":"约数：approximately / roughly / just over / just under / nearly。倍数四种说法：1) A is twice as high as B；2) twice the figure for B；3) a threefold increase；4) doubled/tripled（动词！）。比较句加'夯'：... , compared with + 数字 / while B saw a decline。","ex":["The figure for 2010 was twice as high as that of 2000.","Costs nearly doubled over the period.","Just under half of households owned a car, compared with a quarter in 1990."]},"pr":"1) 用四种倍数句型各写1句。2) 用approximately/just under/compared with写3句。3) 限时15分钟写一个线图Task 1（今天学的东西全用上）。","tip":"倍数句型一出手，考官就知道你是练家子。twice as high as和double这两个表达式，今天必须拿下。"}],"sun":{"t":"第44周自检：Task 1限时写作","obj":"检验图表作文全套技能","pr":"1) 限时20分钟写一篇完整Task 1（任选线图/柱图/表格）。2) 自查清单：有Overview吗？动词分档了吗？超字数吗（150词下限，别超200）？3) 对照范文，抄写3个你没用过的好表达。4) 听写本周25词。","tip":"Task 1是'格式化考试'：结构+句型+词汇都有标准答案。练5篇就能看到清晰进步——这是四科里回报最快的模块。"}},{"w":45,"p":4,"theme":"写作专项二：Task 2 议论文","d":[{"t":"四大题型与审题","obj":"认准题型，避免跑题","time":"45分钟","v":[{"w":"prompt","m":"题目；题干","p":"n.","e":"Read the prompt carefully."},{"w":"stance","m":"立场","p":"n.","e":"State your stance in the introduction."},{"w":"extent","m":"程度","p":"n.","e":"To what extent do you agree?"},{"w":"outweigh","m":"超过；胜过","p":"v.","e":"Do the benefits outweigh the drawbacks?"},{"w":"discuss","m":"讨论","p":"v.","e":"Discuss both views."}],"g":{"t":"四大题型识别","exp":"1) Opinion题：To what extent do you agree?（亮明立场）；2) Discussion题：Discuss both views and give your opinion（两方都要讲+你站谁）；3) Advantage题：Do advantages outweigh disadvantages?（给出裁决：利大于弊）；4) Report题：What are the causes and solutions?（不写立场，只写原因+解决）。审题三问：什么题型？几个任务？立场是什么？答错题型，直接5分。","ex":["Opinion: 'To what extent do you agree or disagree?'","Discussion: 'Some say A, others say B. Discuss both views.'","Report: 'What problems does this cause? What solutions can you suggest?'"]},"pr":"1) 找5道真题，10秒内判断题型+口述文章结构。2) 每种题型各写1个'立场句'。3) 用outweigh/discuss/extent造3句题目用语。","tip":"Task 2跑题是最贵的错误——语言再好也是5分。动笔前花2分钟审题，这2分钟值1分。"},{"t":"开头段写法","obj":"掌握背景改写+亮明观点","time":"45分钟","v":[{"w":"paraphrase","m":"改写；同义转换","p":"v./n.","e":"Paraphrase the question in your intro."},{"w":"background","m":"背景","p":"n.","e":"Open with background, not the copied question."},{"w":"contention","m":"论点；主张","p":"n.","e":"My contention is clear: education matters more."},{"w":"nowadays","m":"如今","p":"adv.","e":"Nowadays, many people work remotely."},{"w":"issue","m":"议题；问题","p":"n.","e":"This is a controversial issue."}],"g":{"t":"开头段公式（2-3句）","exp":"句1 背景改写：把题目换个说法（nowadays/recent years开头+同义替换核心词）。句2 直接亮观点：I believe... / In my view, ... / I firmly agree that...。忌：抄题目原文（露怯）；绕圈子3句才到观点（考官失去耐心）；In the modern world套话开头（减分）。","ex":["Question: Some people think children should start school early.","Intro: In recent years, the age at which children begin formal education has become a topic of debate. In my view, starting later is usually better for their development."]},"pr":"1) 找3道真题，各写一个2句开头（改写+立场）。2) 自查：有没有抄题目原词？3) 用nowadays/issue/contention重组一道题的背景句。","tip":"开头段是'身份证'：告诉考官你读懂题了+你有立场。两句话解决战斗，把墨水留给主体段。"},{"t":"主体段论证","obj":"掌握PEE段落结构","time":"45分钟","v":[{"w":"argument","m":"论点；论证","p":"n.","e":"Each paragraph contains one argument."},{"w":"support","m":"支持；支撑","p":"v./n.","e":"Support the point with an example."},{"w":"instance","m":"例子","p":"n.","e":"For instance, in China..."},{"w":"consequently","m":"因此","p":"adv.","e":"Consequently, productivity improved."},{"w":"emphasize","m":"强调","p":"v.","e":"I want to emphasize the cost."}],"g":{"t":"PEE段落公式","exp":"每段一个论点，PEE展开：Point（本段论点，首句）→ Explain（解释为什么，2-3句：因果链条 therefore/consequently/this means）→ Example（例子落地，for instance/例如中国/瑞典）。一段6-8句，150词内两个主体段。全文两个PEE段+让步段=7分结构。","ex":["P: Remote work saves companies money.","E: This is because offices in city centers are extremely expensive to rent. Consequently, companies that go remote can cut costs significantly.","E(xample): For instance, a study found that firms saved 30% after allowing home working."]},"pr":"1) 任选一道Opinion题，写两个PEE主体段（各150词）。2) 自查：每段第一句是论点吗？例子落地了吗？3) 用consequently/for instance各造2句。","tip":"PEE是议论文的原子结构：论点-解释-例子。段落写不长？不是词穷，是跳过了Explain这一环。"},{"t":"让步与反驳","obj":"掌握Admittedly高分让步段","time":"45分钟","v":[{"w":"admittedly","m":"诚然；无可否认","p":"adv.","e":"Admittedly, technology has its drawbacks."},{"w":"nevertheless","m":"然而","p":"adv.","e":"Nevertheless, the benefits prevail."},{"w":"counterargument","m":"反方论点","p":"n.","e":"Address the counterargument first."},{"w":"valid","m":"有道理的","p":"adj.","e":"This point is valid to some extent."},{"w":"overall","m":"总体上","p":"adv.","e":"Overall, the advantages dominate."}],"g":{"t":"让步段公式","exp":"第三段让步（Discussion/Opinion题都适用）：Admittedly, 反方观点也有道理（1-2句展开）. However/Nevertheless, 反驳：反方的局限/你的立场为何更强（1-2句）. 让步段是考官眼中的'批判性思维'标志，6分与7分的分水岭之一。注意：反驳必须有力，不能让步完就倒戈。","ex":["Admittedly, online education lacks face-to-face interaction, which may reduce motivation for some learners. Nevertheless, its flexibility and low cost make it accessible to far more people, and this outweighs the drawback."]},"pr":"1) 写一个完整让步段（Admittedly... Nevertheless...，60-80词）。2) 把它接到昨天Opinion题的两个PEE段后面。3) 用valid/admittedly造2句。","tip":"会写让步的考生，在考官眼里就'会思考'。这一段是性价比最高的提分模块：一个公式，涨0.5分。"},{"t":"结尾与检查清单","obj":"掌握结尾改写与交卷前5分钟","time":"45分钟","v":[{"w":"conclude","m":"得出结论","p":"v.","e":"To conclude, the benefits dominate."},{"w":"restate","m":"重申","p":"v.","e":"Restate your view in fresh words."},{"w":"proofread","m":"校对","p":"v.","e":"Always leave time to proofread."},{"w":"cohesive","m":"连贯的","p":"adj.","e":"Use cohesive devices naturally."},{"w":"minor","m":"次要的；小的","p":"adj.","e":"Fix minor errors before submitting."}],"g":{"t":"结尾公式 + 交卷检查清单","exp":"结尾1-2句：换个说法重申立场（In conclusion, although... , I believe...），不引入新论点。交卷前5分钟检查清单：1) 主谓一致（he does）；2) 时态统一；3) 单复数（many people are）；4) 冠词（a/the）；5) 拼写（government/environment/recieve→receive）；6) 字数250+。这5分钟能救回0.5分。","ex":["In conclusion, while remote work is not perfect, I believe its benefits clearly outweigh its drawbacks.","Check: 'The government have' -> 'The government has'."]},"pr":"1) 给本周的完整文章写结尾。2) 拿出全文，用6项清单逐项检查，数出错误。3) 把自己的高频错误（前3名）写在错题本首页。","tip":"语言分不看你写得多高级，看你错得多不多。交卷前5分钟的清单检查，是写作最便宜的提分手段。"}],"sun":{"t":"第45周自检：Task 2限时写作","obj":"检验议论文全套技能","pr":"1) 限时40分钟写一篇完整Task 2（真题任选）。2) 自查：四段结构？PEE齐？让步段有？结尾有？字数250+？3) 用6项清单挑错并修改。4) 听写本周25词+滚动词汇。","tip":"Task 2占写作分值2/3，务必练到'结构条件反射化'：拿到题就知道每段写什么。此时你已有全部组件，下周开始拼装实战。"}},{"w":46,"p":4,"theme":"口语专项：Part 2 话题库","d":[{"t":"人物类话题","obj":"掌握Describe a person答题框架","time":"45分钟","v":[{"w":"personality","m":"个性","p":"n.","e":"She has a warm personality."},{"w":"admire","m":"钦佩","p":"v.","e":"I admire her determination."},{"w":"generous","m":"慷慨的","p":"adj.","e":"He is generous with his time."},{"w":"inspire","m":"激励","p":"v.","e":"Her story inspires me to try harder."},{"w":"supportive","m":"支持的；给予帮助的","p":"adj.","e":"My parents are always supportive."}],"g":{"t":"人物卡四层展开","exp":"人物卡（Describe a person who...）：1) 是谁+怎么认识的（2句）；2) 外貌或性格（1-2句，用which/who从句加分）；3) 一件具体的事（3-4句，故事主体，占一半时间）；4) 这人对你的影响/你为什么admire（2句收尾）。素材复用：准备'一位老师'，可套'帮助过你的人/有趣的人/你想再见的人'多张卡。","ex":["The person I'd like to describe is my high school English teacher, Ms. Chen, who taught me for three years.","She is the kind of person who always stays calm, even when everything goes wrong.","Because of her, I started to believe that I could learn English well."]},"pr":"1) 准备'一位老师'素材，按四层写笔记（关键词，不写全文）。2) 录音2分钟。3) 数一数用了几个从句、几个高级形容词。","tip":"Part 2的秘密是'素材库'：5个人物素材串起20张人物卡。别一张卡一个故事，那是给自己加十倍的量。"},{"t":"事件类话题","obj":"掌握Describe an event故事线","time":"45分钟","v":[{"w":"occasion","m":"场合；（重要）活动","p":"n.","e":"It was a special occasion."},{"w":"memorable","m":"难忘的","p":"adj.","e":"It was the most memorable day of my life."},{"w":"celebrate","m":"庆祝","p":"v.","e":"We celebrated my grandmother's birthday."},{"w":"participate","m":"参与","p":"v.","e":"I participated in a speech contest."},{"w":"unexpectedly","m":"出乎意料地","p":"adv.","e":"Unexpectedly, I won first prize."}],"g":{"t":"事件卡五要素","exp":"事件卡（Describe an event/experience）：When（时间背景1句）→ Where（地点+场景细节1句）→ Who（人物1句）→ What（发生了什么，3-4句，用转折制造故事性：suddenly/unfortunately/luckily）→ Feeling（你的感受+影响，2句）。'一次比赛/一次旅行/一个惊喜'素材可串'挑战/成功/难忘/改变你的事'多卡。","ex":["Last summer, I took part in a hiking trip with my classmates.","Unfortunately, it started to rain heavily halfway up the mountain.","That experience taught me to stay calm under pressure."]},"pr":"1) 准备'一次难忘的比赛/旅行'素材，按五要素写关键词笔记。2) 录音2分钟。3) 强制使用：suddenly / unexpectedly / luckily。","tip":"事件卡讲得好不好，全看'故事感'：平铺直叙没人听，一个suddenly就有戏。考官一天听80个'难忘的事'，让他记住你的那个。"},{"t":"地点类话题","obj":"掌握Describe a place框架","time":"45分钟","v":[{"w":"scenery","m":"风景","p":"n.","e":"The scenery there is breathtaking."},{"w":"atmosphere","m":"氛围","p":"n.","e":"The cafe has a relaxing atmosphere."},{"w":"historic","m":"有历史意义的","p":"adj.","e":"It is a historic town."},{"w":"peaceful","m":"宁静的","p":"adj.","e":"The village is peaceful and quiet."},{"w":"crowded","m":"拥挤的","p":"adj.","e":"The street gets crowded on weekends."}],"g":{"t":"地点卡四步","exp":"地点卡（Describe a place you like to visit）：1) 位置+怎么知道它的（1-2句，用located in）；2) 外观/特点（2句，there be句型+形容词堆叠：peaceful/historic/crowded）；3) 你在那做什么/什么时候去（2句， frecuencia：I go there whenever...）；4) 为什么喜欢（2句，收尾升华）。'一个公园/一家咖啡馆/一个城市'可串多卡。","ex":["There is a small park located near my home, which I visit almost every weekend.","What makes it special is the peaceful atmosphere, especially in early morning.","That's why it has become my favorite place to recharge."]},"pr":"1) 准备'一个常去的公园/咖啡馆'素材，按四步写关键词。2) 录音2分钟，强制用there be两句+located in。3) 用scenery/atmosphere/peaceful造3句。","tip":"地点卡的灵魂是'个人化细节'：不说公园很美，说'清晨的公园里有遛狗的老人和跑步的学生'。画面感，就是高分感。"},{"t":"物品类话题","obj":"掌握Describe an object框架","time":"45分钟","v":[{"w":"gadget","m":"小装置；小玩意","p":"n.","e":"My favorite gadget is my e-reader."},{"w":"practical","m":"实用的","p":"adj.","e":"It is small but practical."},{"w":"function","m":"功能","p":"n.","e":"Its main function is... "},{"w":"valuable","m":"贵重的；有价值的","p":"adj.","e":"The gift was valuable to me."},{"w":"convenient","m":"方便的","p":"adj.","e":"It makes my life more convenient."}],"g":{"t":"物品卡四层","exp":"物品卡（Describe an object you value）：1) 是什么+谁给的/怎么来的（2句）；2) 外观（1-2句：大小颜色材质）；3) 功能/你怎么用它（2-3句，频率+场景）；4) 为什么珍贵（2句，情感升华：不是钱的问题，是回忆/意义）。'一件礼物/一个电子设备/一件旧物'可串多卡。","ex":["The object I want to describe is an old dictionary my grandfather gave me.","Although it looks ordinary, it means the world to me.","Whenever I open it, I remember how he encouraged me to learn."]},"pr":"1) 准备'一件有意义的礼物'素材，按四层写关键词。2) 录音2分钟。3) 强制使用：practical / convenient / valuable各1次。","tip":"物品卡的高分钥匙在第4层：'为什么珍贵'。说出情感故事（who gave it, why it matters），普通物品立刻变得动人。"},{"t":"串题法与Part 3","obj":"掌握一材多用与深度讨论技巧","time":"45分钟","v":[{"w":"versatile","m":"多用途的","p":"adj.","e":"One story can be versatile."},{"w":"anecdote","m":"轶事；小故事","p":"n.","e":"Prepare anecdotes, not scripts."},{"w":"generalize","m":"概括；泛化","p":"v.","e":"Part 3 asks you to generalize."},{"w":"speculate","m":"推测","p":"v.","e":"You may speculate about the future."},{"w":"society","m":"社会","p":"n.","e":"How does this affect society?"}],"g":{"t":"串题法 + Part 3 攻略","exp":"串题：你的5个素材（1人1事1地1物+1个'学习英语的经历'）能覆盖90%话题卡——练习时先想'这题能不能套旧素材'，改开头结尾即可。Part 3：考官问的是'社会层面'（Why do people...? / What effects...?），答题公式：直接观点→原因/结果→例子（In China...）→（可选）让步。每题说20-30秒，别抢也别冷场。","ex":["Topic: A person you admire -> use 'my teacher' story","Topic: A time you helped someone -> adapt the same story","Part 3: 'Why do people keep old objects?' -> Sentimental value + example (photos, letters)"]},"pr":"1) 列出你的5大素材，各写出能套的3张卡。2) 随机抽3张新题卡，口测能否30秒内想好套哪个素材。3) 录音回答3道Part 3题（每题30秒）。","tip":"高手不背100个故事，而是把5个故事打磨到能应对100张卡。串题法练熟，考试前一晚你只需要复习5页笔记。"}],"sun":{"t":"第46周自检：口语Part 2全库演练","obj":"检验四类话题卡与串题能力","pr":"1) 随机抽5张话题卡（人物/事件/地点/物品+任一），每张准备1分钟后录音2分钟。2) 回听打分：流畅度/词汇/语法/发音各1-5分。3) 哪类卡最弱？明天起每天加练1张。4) 听写本周25词。","tip":"口语的终极对手是'冷启动'——抽到没见过的题。串题法就是你的防弹衣：世上没有新题，只有旧素材的新包装。"}},{"w":47,"p":4,"theme":"全真模考一：摸底定位","d":[{"t":"听力全真模考","obj":"完成第一轮听力全真测试","time":"60分钟","v":[{"w":"authentic","m":"真实的；真题的","p":"adj.","e":"Use authentic test materials."},{"w":"simulate","m":"模拟","p":"v.","e":"Simulate real exam conditions."},{"w":"strict","m":"严格的","p":"adj.","e":"Follow strict timing."},{"w":"condition","m":"条件；状态","p":"n.","e":"Exam conditions matter."},{"w":"transfer","m":"转写；誊写","p":"v.","e":"Transfer answers in the last ten minutes."}],"g":{"t":"全真模考规则","exp":"规则一：一次性完成，中途不暂停、不回放、不查词典。规则二：严格计时——听力30分钟播放+10分钟誊写答案。规则三：只使用真题（剑桥系列），不用模拟题。规则四：做完当天必须精析（明天任务），否则模考白做。分数先别在意，这轮是'体检'。","ex":["Do not pause the audio, even once.","Use the 10 minutes to transfer answers carefully.","Record your score in your error log."]},"pr":"1) 完成一套完整听力真题（40题）。2) 誊写答案后对答案，记录原始分。3) 把分数写进'成长曲线表'（第47周：第一格）。","tip":"第一次模考的分数不是终点，是起点坐标。它的唯一作用是告诉你：离6.5还差几题、差在哪个Section。"},{"t":"阅读全真模考","obj":"完成第一轮阅读全真测试","time":"60分钟","v":[{"w":"consecutive","m":"连续的","p":"adj.","e":"Three passages in one hour."},{"w":"endurance","m":"耐力","p":"n.","e":"Reading tests your endurance."},{"w":"concentration","m":"专注力","p":"n.","e":"Keep concentration for 60 minutes."},{"w":"accuracy","m":"准确率","p":"n.","e":"Speed matters, but accuracy matters more."},{"w":"register","m":"登记；记录","p":"v.","e":"Register your time for each passage."}],"g":{"t":"连考耐力训练","exp":"今天在听力模考后紧接着做阅读（中间只休10分钟），模拟真实考场疲劳。这是很多人忽略的：单独做阅读6.5，连考只剩6——大脑需要练习'续航'。阅读时旁边放个计时器，每篇开始时记一笔实际用时。","ex":["Passage 1: start 0:00, finish 0:19.","Passage 2: start 0:21, finish 0:43.","Passage 3: rushed - only 17 minutes left."]},"pr":"1) 连续完成3篇阅读真题（60分钟）。2) 记录每篇实际用时。3) 对答案，记录分数到成长曲线表。","tip":"累，就对了。今天的目的之一就是体验'第三篇时脑子发木'——你会在第49周学会分配体力，让这种感觉迟到。"},{"t":"听力精析日","obj":"吃透听力模考的每个错误","time":"60分钟","v":[{"w":"analyze","m":"分析","p":"v.","e":"Analyze every wrong answer."},{"w":"pattern","m":"模式；规律","p":"n.","e":"Find your error pattern."},{"w":"weakness","m":"弱项","p":"n.","e":"Everyone has a weakness to fix."},{"w":"root","m":"根源","p":"n.","e":"Find the root cause."},{"w":"replay","m":"重放","p":"v.","e":"Replay the tricky sentences."}],"g":{"t":"精析三问法","exp":"对每个错题问三个问题：1) 错在哪一类？（没听到/听到了没反应/反应了没写对）2) 根源是什么？（替换词不认识/走神/拼写/单复数）3) 怎么防？（针对性动作：如'每晚5分钟数字听写'）。把答案填进'错题归因表'，一周后你会看到自己的错误规律——规律就是训练计划。","ex":["Q12 wrong: heard 'deposit' but wrote 'deposite' -> spelling drill.","Q23 wrong: missed 'but actually' -> train transition words.","Q31 wrong: didn't know 'fortnight' = two weeks -> vocab."]},"pr":"1) 把听力错题全部归因填表（类型/根源/对策三列）。2) 统计：哪类错误最多？3) 挑10个最典型错句做精听。","tip":"模考不精析=白考。错误是你的私人情报，分析它就是在给6.5画路线图。"},{"t":"阅读精析日","obj":"吃透阅读模考的每个错误","time":"60分钟","v":[{"w":"trap","m":"陷阱","p":"n.","e":"Recognize the trap in each question."},{"w":"misread","m":"误读","p":"v.","e":"I misread the question stem."},{"w":"locate","m":"定位","p":"v.","e":"Did I locate the right sentence?"},{"w":"paraphrase","m":"同义替换","p":"n.","e":"Every correct answer is a paraphrase."},{"w":"regret","m":"后悔；遗憾","p":"v.","e":"Avoid 'silly mistake' regrets."}],"g":{"t":"阅读错题四归因","exp":"阅读错题只有四种：1) 定位错（找错句子）；2) 替换不识（定位对了，没认出同义替换）；3) 理解错（句子读懂了吗）；4) 马虎错（抄错/字数超/看错NOT）。给每题打标签：1类练定位特征词，2类积累替换对，3类做长难句，4类上检查清单。四类错误四种药，别乱吃。","ex":["Type 2: 'buying' vs 'purchase' - add to synonym list.","Type 4: wrote 4 words under 'NO MORE THAN THREE WORDS'.","Type 1: circled wrong keyword - chose a common word."]},"pr":"1) 给阅读错题逐题打四类标签。2) 统计各类型占比。3) 把所有'替换不识'整理进替换本（今天的收获清单）。","tip":"马虎错最冤但最好治：把'检查字数/NOT/大小写'写进考试流程，2分钟解决。能力错要时间，习惯错要纪律。"},{"t":"写作口语模考","obj":"完成写作口语首轮自测","time":"90分钟","v":[{"w":"script","m":"手写；答卷","p":"n./v.","e":"Write by hand - the real exam is on paper."},{"w":"rubric","m":"评分标准","p":"n.","e":"Grade yourself with the official rubric."},{"w":"benchmark","m":"基准；参照","p":"n.","e":"Compare your essay with a benchmark essay."},{"w":"criteria","m":"标准（复数）","p":"n.","e":"Four criteria for each skill."},{"w":"band","m":"分数段","p":"n.","e":"Estimate your current band."}],"g":{"t":"写作口语自评法","exp":"写作：限时60分钟完成Task 1（20分钟）+Task 2（40分钟），必须手写。自评四项：Task Response（切题吗）/ Coherence（结构顺吗）/ Lexis（词汇分档吗）/ Grammar（错误多吗），各估一个band，取平均。口语：完整录三Part（14分钟），对照四项标准自评。没把握就找一篇同题范文对比差距。","ex":["Task 2 self-check: Did I state a clear position?","Did my overview exist in Task 1?","Count grammar errors: 8 in 250 words = too many."]},"pr":"1) 限时60分钟手写Task 1+Task 2。2) 四项标准逐项自评打分。3) 口语完整录音一套，回听自评。4) 分数记入成长曲线表。","tip":"写作口语自评偏低是正常的——你对自己最严格。重点不是分数，是找出'四项里最矮的那块板'，那就是下周的靶心。"}],"sun":{"t":"第47周自检：模考盘点与弱项定位","obj":"汇总四科分数，制定冲刺计划","pr":"1) 汇总四科分数，对照6.5目标算差距：每科差几分？2) 写'弱项清单'：每科列前2个弱点+对应训练动作。3) 制定第48周弱项突破计划（精确到每天做什么）。4) 听写本周25词。","tip":"这周你干了一件大事：把自己'测量'了出来。接下来的每一周都是对着这份测量报告打靶——这就是科学的备考。"}},{"w":48,"p":4,"theme":"弱项突破周：定点爆破","d":[{"t":"听力弱项突破","obj":"集中打击听力最弱环节","time":"60分钟","v":[{"w":"drill","m":"训练；操练","p":"n./v.","e":"Do targeted drills, not random practice."},{"w":"intensive","m":"密集的；强化的","p":"adj.","e":"Intensive practice beats casual listening."},{"w":"threshold","m":"门槛","p":"n.","e":"Push past your threshold."},{"w":"breakthrough","m":"突破","p":"n.","e":"This week is about breakthroughs."},{"w":"persistent","m":"坚持的","p":"adj.","e":"Be persistent with weak spots."}],"g":{"t":"定点爆破法","exp":"只练错得最多的题型/场景：地图题弱就一天3套地图；数字弱就一天50组数字听写；Section 4怕就一天精听2篇讲座。原则：一个弱项连续打5天，每天30-40题，直到正确率到80%再换下一个。分散练习不如集中火力——'哪里不会补哪里'效率最高。","ex":["Weakness: map questions. Plan: 3 map drills daily for 5 days.","Weakness: numbers. Plan: 50-number dictation each evening."]},"pr":"1) 按弱项清单执行听力定点训练（今天第1天，30题以上）。2) 记录正确率。3) 睡前10分钟数字/拼写听写（连续5天不断）。","tip":"弱项突破期最枯燥，但回报最实在。三天后你会感到'原来怕的题变熟了'——那正是分数在生长的声音。"},{"t":"阅读弱项突破","obj":"集中打击阅读最弱题型","time":"60分钟","v":[{"w":"tackle","m":"对付；解决","p":"v.","e":"Tackle the hardest question type first."},{"w":"conquer","m":"攻克","p":"v.","e":"Conquer headings questions this week."},{"w":"gradually","m":"逐渐地","p":"adv.","e":"Accuracy improves gradually."},{"w":"method","m":"方法","p":"n.","e":"Trust the method, not luck."},{"w":"rhythm","m":"节奏","p":"n.","e":"Find your rhythm in scanning."}],"g":{"t":"单题型刷题法","exp":"选你最弱的题型（如段落信息匹配）：1) 一天只刷这一种题型，20题起；2) 每题做完必写'定位词是什么、答案在哪句'；3) 错题当场分析，连续做5天；4) 第5天混入其他题型，验证'单兵能力'能否转化为'实战能力'。此法对每种题型都适用，专治'某种题永远错一半'。","ex":["Day 1-4: 20 matching questions daily.","Day 5: mixed test - matching accuracy should now hold."]},"pr":"1) 执行弱项题型专项（今天20题+归因）。2) 建一张'题型正确率追踪表'，每天更新。3) 复习本周精析的替换词本。","tip":"题型突破像凿井：找准一点（题型），连凿五天，直到出水（正确率稳定80%）。东一锹西一锹，永远只挖出干土。"},{"t":"写作弱项突破","obj":"改稿比写稿更重要","time":"60分钟","v":[{"w":"rewrite","m":"重写；改写","p":"v.","e":"Rewrite your essay twice."},{"w":"polish","m":"润色","p":"v.","e":"Polish the language in round three."},{"w":"upgrade","m":"升级","p":"v.","e":"Upgrade weak sentences with better structures."},{"w":"refine","m":"改进；精炼","p":"v.","e":"Refine your word choice."},{"w":"internalize","m":"内化","p":"v.","e":"Internalize the corrections."}],"g":{"t":"一篇改三遍法","exp":"拿出一篇你写过的文章：第一遍改结构（论点是否明确、PEE是否齐全、让步是否有力）；第二遍改论证（解释是否充分、例子是否落地）；第三遍改语言（把所有'I think'换掉、简单词升级、检查语法）。每遍对照同一个评分标准。改完抄一遍终稿——好句子是改出来的，更是抄进肌肉记忆的。","ex":["Round 1: Add a concession paragraph after two PEE paragraphs.","Round 2: The example 'many people' -> 'for instance, in many Chinese cities'.","Round 3: 'good' -> 'beneficial'; check all third-person 's'."]},"pr":"1) 选一篇旧作执行'三遍改稿法'（今天完成第1、2遍）。2) 明天完成第3遍并誊抄终稿。3) 把改稿中发现的高频错误记进错题本。","tip":"写作的秘密：写10篇不如改1篇。每改一遍，你就'升维'一次看文章的眼光——考场上你的第一稿水平，取决于你改稿的眼光。"},{"t":"口语弱项突破","obj":"针对流利度或词汇做专项","time":"60分钟","v":[{"w":"hesitate","m":"犹豫；停顿","p":"v.","e":"Don't hesitate - use fillers."},{"w":"filler","m":"填充语","p":"n.","e":"Well, let me think, you know..."},{"w":"fluency","m":"流利度","p":"n.","e":"Fluency is trainable."},{"w":"intonation","m":"语调","p":"n.","e":"Copy the intonation of native speakers."},{"w":"coherent","m":"连贯的","p":"adj.","e":"Keep your answer coherent."}],"g":{"t":"流利度专项训练","exp":"1) 录一段2分钟回答，数一数'呃''嗯'和无声停顿的次数（大多数人是10次以上）；2) 用well / you know / let me think 替代沉默，把停顿变成'有声思考'；3) 跟读法：选1分钟地道音频，模仿到语调一样（每天15分钟）；4) 同一话题连说3遍录音，一遍比一遍顺——第三遍就是你的'真实水平'。","ex":["Instead of: 'Errr... I think... errr...'","Say: 'Well, I'd say that... you know, it's mainly because...'","Repeat the same topic 3 times - track improvement."]},"pr":"1) 录音2分钟并数停顿次数。2) 用'有声填充'重录一遍，对比次数。3) 跟读15分钟地道材料。","tip":"流利度不是说得快，是没有'死机'。考官不怕你慢，怕你'断电'——well和you know就是你的备用电源。"},{"t":"词汇查缺补漏","obj":"错误率最高的词二刷","time":"60分钟","v":[{"w":"consolidate","m":"巩固","p":"v.","e":"Consolidate what you almost know."},{"w":"review","m":"复习","p":"v./n.","e":"Review beats new learning now."},{"w":"reinforce","m":"强化","p":"v.","e":"Reforce the weakest words."},{"w":"retention","m":"记忆保持","p":"n.","e":"Spaced review improves retention."},{"w":"master","m":"掌握","p":"v.","e":"Master the words you keep missing."}],"g":{"t":"错词二刷法","exp":"只重做'错过两次以上'的词：1) 从错题本挑出这些顽固词（一般50-100个）；2) 每天20个，看中文默写英文+口拼一遍；3) 写不出的进'顽固词卡盒'，三天后再测；4) 直到连续两次全对才出盒。现在背新词性价比低——把'半熟词'变成'熟词'，才是最后的涨分点。","ex":["Box 1: missed twice - test today.","Missed again? -> stays in the box 3 more days.","Two clean passes -> word graduates."]},"pr":"1) 整理顽固词卡盒（今天第一批20词）。2) 默写+口拼各一遍。3) 三天后（第51周）复测，全对出盒。","tip":"一年下来你学过1300+词。最后拼的不是谁的词汇多，而是谁的'半熟词'少——二刷就是最后的清仓。"}],"sun":{"t":"第48周自检：弱项复测","obj":"验证一周定点爆破的成果","pr":"1) 把本周弱项题型再测一组（同等难度）：正确率到80%了吗？2) 口语重录那道2分钟题：停顿次数降了多少？3) 默写顽固词第一批：出盒几个？4) 更新成长曲线表，写下下周模考目标分。","tip":"定点爆破一周，弱项应该'肉眼可见'地好转。如果没到80%，别慌——说明找到了'真弱项'，下周继续打，突破往往发生在第二周。"}},{"w":49,"p":4,"theme":"全真模考二：时间管理","d":[{"t":"笔试连考模拟","obj":"三小时连考，训练真实体力","time":"3小时","v":[{"w":"stamina","m":"耐力；体力","p":"n.","e":"Three hours demands stamina."},{"w":"routine","m":"常规；流程","p":"n.","e":"Build your exam-day routine."},{"w":"consistent","m":"一致的；稳定的","p":"adj.","e":"Consistent performance beats peaks."},{"w":"simulate","m":"模拟","p":"v.","e":"Simulate the real schedule: start at 9 am."},{"w":"hydrate","m":"补水","p":"v.","e":"Hydrate before, not during."}],"g":{"t":"三小时连考战术","exp":"完全按真实节奏：上午9:00开考，听力（30+10分钟）→ 不休息 → 阅读60分钟 → 不休息 → 写作60分钟。中途只允许喝一口水。这是很多考生第一次完整连考——第三小时（写作）会明显感觉手酸脑木，正是训练目的：学会在疲劳中保持质量。写作时如果手写累到变形，主动放慢10%速度，稳住字迹。","ex":["9:00 - 9:40 Listening + transfer","9:45 - 10:45 Reading","10:45 - 11:45 Writing - stay calm, steady hand."]},"pr":"1) 上午完成三小时连考（真实作息）。2) 每科结束立刻记一笔'疲劳度'（1-5分）。3) 对答案，分数记入成长曲线表。","tip":"连考跟马拉松一样，35公里处才知道自己的真面目。今天流的汗，就是考场上别人慌张时你从容的底气。"},{"t":"连考精析日","obj":"对比第47周，确认进步与残留问题","time":"60分钟","v":[{"w":"compare","m":"对比","p":"v.","e":"Compare with round one."},{"w":"statistics","m":"统计（数据）","p":"n.","e":"Let the statistics speak."},{"w":"trend","m":"趋势","p":"n.","e":"Is the trend going up?"},{"w":"adjust","m":"调整","p":"v.","e":"Adjust the plan based on data."},{"w":"plateau","m":"平台期","p":"n.","e":"A plateau means the method needs a tweak."}],"g":{"t":"两轮对比分析法","exp":"把第49周和第47周的分数放在一起：1) 涨了的科目——保持现有做法；2) 没动的科目——检查是不是方法问题而非练习量问题；3) 降了的科目——多半是疲劳或状态，看错误类型是否相同。结论写下来：最后三周，每科'保持什么+加强什么'各一条。数据不说谎，感觉会。","ex":["Listening: 26 -> 30 (+4) - keep the daily dictation.","Reading: 29 -> 29 (plateau) - check error types: still matching?","Writing: unchanged - add one more rewrite session."]},"pr":"1) 制作两轮分数对比表（四科+细项）。2) 每科写'保持+加强'各1条。3) 更新最后三周计划。","tip":"两轮模考的对比，是给自己最诚实的反馈。涨了的，是你努力的可视化；没涨的，是最后冲刺的路标。"},{"t":"写作限时模考","obj":"60分钟连写双任务的最后演练","time":"60分钟","v":[{"w":"compose","m":"写作；构成","p":"v.","e":"Compose both tasks in 60 minutes."},{"w":"allocate","m":"分配","p":"v.","e":"Allocate 20 minutes to Task 1, 40 to Task 2."},{"w":"submit","m":"提交；交卷","p":"v.","e":"Stop writing when time is up."},{"w":"handwriting","m":"书写；字迹","p":"n.","e":"Keep handwriting readable."},{"w":"legible","m":"清晰可读的","p":"adj.","e":"Answers must be legible."}],"g":{"t":"60分钟写作战术","exp":"0-1分钟：读题+审题（Task 2题型判断）。1-3分钟：Task 2列提纲（四段各一句要点，箭头连接）——3分钟换40分钟不慌。3-23分钟：写Task 1（150词）。23-55分钟：写Task 2（250词）。55-60分钟：检查（先查Task 2：时态/单复数/拼写，再查Task 1字数与Overview）。提纲是保险绳：写着写着忘了立场，看一眼提纲。","ex":["Minute 3-23: Task 1 (overview must exist).","Minute 23-55: Task 2 (follow the outline).","Minute 55-60: proofread, count words, check handwriting."]},"pr":"1) 严格按战术时间表完成60分钟写作。2) 每段用时记录。3) 自评+记录分数变化。","tip":"写作6.5的最大敌人是'Task 2没写完'。3分钟提纲看似奢侈，实则是让你40分钟全程不打草稿的魔法。"},{"t":"口语全流程模拟","obj":"11-14分钟全流程演练","time":"45分钟","v":[{"w":"interview","m":"面试；面谈","p":"n.","e":"The speaking test is a friendly interview."},{"w":"greeting","m":"问候；打招呼","p":"n.","e":"A natural greeting sets the tone."},{"w":"natural","m":"自然的","p":"adj.","e":"Sound natural, not memorized."},{"w":"confident","m":"自信的","p":"adj.","e":"Confidence is half the score."},{"w":"farewell","m":"告别","p":"n.","e":"End with a smile and farewell."}],"g":{"t":"口试全流程演练","exp":"完整流程：敲门进场问好（Good morning!）→ 出示证件 → 考官提问身份类问题（姓名/ hometown/工作学习）→ Part 1（4-5分钟）→ Part 2（1分钟准备+2分钟陈述）→ Part 3（4-5分钟讨论）→ 告别（Thank you. Have a nice day!）。全程录像而不只是录音：检查眼神（看镜头如看考官）、坐姿（别瘫别抖）、微笑。评分时考官的'印象分'真实存在。","ex":["Enter: Good morning! (smile, eye contact)","Part 2: Use the 1 minute to write 4 keywords, not sentences.","Exit: Thank you very much. Have a great day!"]},"pr":"1) 全流程录像模拟（找人当考官，或对镜头自演）。2) 回看录像：记3个肢体语言问题。3) 改掉它们再录一遍。","tip":"口语考的不只是英语，还有'你这个人'。录像里的那个自己——眼神、微笑、坐姿——就是考官眼里的你。让他看到一个想给你加分的人。"},{"t":"考场时间红线","obj":"固化各科时间纪律","time":"45分钟","v":[{"w":"budget","m":"预算（时间）","p":"n./v.","e":"Your time budget is law."},{"w":"prioritize","m":"优先","p":"v.","e":"Prioritize questions you can win."},{"w":"skip","m":"跳过","p":"v.","e":"Skip and mark - never freeze."},{"w":"red line","m":"红线（底线）","p":"n.","e":"90 seconds per stuck question - red line."},{"w":"monitor","m":"监控","p":"v.","e":"Monitor your pace every 10 minutes."}],"g":{"t":"时间红线清单","exp":"听力：誊写只给10分钟，5分钟誊完+5分钟检查（大小写/字数/拼写）。阅读：每篇20分钟红线，卡题90秒必跳；最后2分钟必须留给'有没有漏题'。写作：Task 1到20分钟必须收笔，无论写到哪。口语：Part 2说满1.5-2分钟，被打断是正常的（说明你说够了）。把红线写在一张卡片上，模考时放手边。","ex":["Listening: transfer finished by minute 5.","Reading: stuck 90 seconds? Mark, skip, move.","Writing: Task 1 pen down at minute 20 - no exceptions."]},"pr":"1) 写自己的'四科时间红线卡'。2) 用红线卡重做今天任一科的一组题验证。3) 把卡片拍照设为手机壁纸。","tip":"考场上真正的主宰不是英语水平，是时间纪律。红线卡不是建议，是军令——练到身体自动执行。"}],"sun":{"t":"第49周自检：两轮模考对比复盘","obj":"确认进步曲线，锁定最后冲刺点","pr":"1) 完成两轮分数对比图（四科两轮柱状对比，手画即可）。2) 写最后三周计划：每科1个保持项+1个加强项。3) 顽固词盒复测。4) 口语：抽3张卡录音，对比第46周的自己。","tip":"看到两根柱子的差距了吗？那叫成长。还差的那一点，就是最后三周的全部任务——目标从没像今天这样清晰。"}},{"w":50,"p":4,"theme":"高频话题与语言总复习","d":[{"t":"教育与工作话题","obj":"打包复习最高频话题词汇与论点","time":"60分钟","v":[{"w":"curriculum","m":"课程（体系）","p":"n.","e":"The curriculum needs updating."},{"w":"qualification","m":"资格；学历","p":"n.","e":"A degree is not the only qualification."},{"w":"salary","m":"薪水","p":"n.","e":"Salary is not the only factor."},{"w":"motivation","m":"动力；动机","p":"n.","e":"Intrinsic motivation lasts longer."},{"w":"career","m":"职业；事业","p":"n.","e":"Career paths are changing."}],"g":{"t":"话题打包复习法","exp":"教育和工作是写作口语双料最高频话题。把话题词打包记忆：一张思维导图（工作话题）分四枝——选择工作（salary/motivation/interest）、工作方式（remote/flexible）、职业发展（promotion/skill）、社会影响（equality/economy）。口语Part 3和写作Task 2共用这套词汇。每个枝头写2个论点句，一张图=10个话题的弹药。","ex":["Branch 1: choosing a job - salary vs interest.","Branch 2: remote work - flexibility vs isolation.","论点句: Motivation, not salary, determines long-term success."]},"pr":"1) 画'工作话题'思维导图（四枝各3词）。2) 每枝写1个论点句（共4句）。3) 口头回答：What makes a good job?（用上今天5词）。","tip":"雅思话题不过20个大类，每个大类一张导图。图连成网，任何题你都有两个论点和五个词等着它。"},{"t":"科技与环境话题","obj":"复习双料高频话题的正反论据","time":"60分钟","v":[{"w":"innovation","m":"创新","p":"n.","e":"Innovation drives progress."},{"w":"sustainable","m":"可持续的","p":"adj.","e":"We need sustainable solutions."},{"w":"emission","m":"排放","p":"n.","e":"Carbon emissions keep rising."},{"w":"renewable","m":"可再生的","p":"adj.","e":"Renewable energy is getting cheaper."},{"w":"digital","m":"数字的","p":"adj.","e":"The digital economy is expanding."}],"g":{"t":"环保科技论据库","exp":"正方（科技利）：提高效率（efficiency）、远程协作减少通勤排放、可再生能源成本下降。反方（科技弊）：电子垃圾（e-waste）、设备更新快造成浪费、算法加剧能源消耗。环境类万能方案三件套：政府立法（regulation）+企业转型（green technology）+个人习惯（reduce, reuse, recycle）。每个论据配1个具体例子（如瑞典的垃圾发电）。","ex":["Pro: Remote work cuts commuting emissions.","Con: Fast device turnover creates e-waste.","Solution trio: regulation, green tech, personal habits."]},"pr":"1) 写'科技与环保'正反论据各3条（各配1例）。2) 口头小作文：Should companies go fully remote?（90秒）。3) 用sustainable/renewable/emission造3句。","tip":"科技环保题几乎每年必考。论据库备好，考场上你是在'默写'，别人在'创作'——这就是不公平的优势。"},{"t":"社会与政府话题","obj":"掌握政府类题目的万能角度","time":"60分钟","v":[{"w":"welfare","m":"福利","p":"n.","e":"The welfare system supports families."},{"w":"policy","m":"政策","p":"n.","e":"Government policy can guide behavior."},{"w":"taxation","m":"税收","p":"n.","e":"Taxation funds public services."},{"w":"equality","m":"平等","p":"n.","e":"Education promotes equality."},{"w":"regulate","m":"监管；管制","p":"v.","e":"Governments should regulate advertising."}],"g":{"t":"政府类万能四角度","exp":"问'政府该不该做X'，从四个角度组织论点：1) 资金（税收该花在哪 funding allocation）；2) 法律（立法与监管 regulate/legislate）；3) 教育（宣传引导 public awareness campaigns）；4) 权责边界（个人自由 vs 政府责任 individual freedom）。任何政府题都能从这四格里抽论点。经典立场：政府该管基础设施和规则，但不该替个人做选择。","ex":["Funding: Tax revenue should prioritize healthcare.","Law: Only legislation can enforce emission standards.","Boundary: Governments guide; individuals choose."]},"pr":"1) 用四角度写'政府该不该禁止垃圾食品广告'的论点提纲（4条）。2) 口头展开其中2条。3) 用welfare/taxation/regulate造3句。","tip":"政府题写着写着就'无话可说'？那是你没带'四角度'上场。弹药匣有四个格子，怎么也够打一场仗。"},{"t":"文化与媒体话题","obj":"掌握双刃剑模板","time":"60分钟","v":[{"w":"heritage","m":"遗产（文化）","p":"n.","e":"Cultural heritage must be protected."},{"w":"diversity","m":"多样性","p":"n.","e":"Cultural diversity enriches society."},{"w":"influence","m":"影响","p":"n./v.","e":"Media influence on children is huge."},{"w":"advertisement","m":"广告","p":"n.","e":"Advertisements shape consumption."},{"w":"entertainment","m":"娱乐","p":"n.","e":"Entertainment is not the enemy."}],"g":{"t":"双刃剑模板","exp":"文化与媒体题的万能框架——好处：信息与娱乐（access to information / entertainment value）、促进理解（promote understanding and diversity）、保存文化（preserve heritage）。坏处：成瘾（addiction）、误导（misleading content）、同质化（cultural homogenization）。结论万能句：关键在使用者（It depends on how we use it）或需要监管+教育双管齐下。","ex":["Pro: Media gives everyone access to information.","Con: Algorithms feed addiction and misinformation.","Verdict: The key lies in regulation and media literacy."]},"pr":"1) 用双刃剑模板写'社交媒体利弊'完整提纲（正3+反3+结论）。2) 口头说90秒。3) 用heritage/diversity/influence造3句。","tip":"双刃剑模板几乎覆盖一切'X是利大于弊吗'的题。模板不是套路，是安全网——保证你永远有话说，且说得有条理。"},{"t":"高分句型总复习","obj":"唤醒全年学过的提分句型","time":"60分钟","v":[{"w":"inversion","m":"倒装","p":"n.","e":"Not only does it save money..."},{"w":"emphatic","m":"强调的","p":"adj.","e":"It is education that changes lives."},{"w":"relative","m":"关系的（从句）","p":"adj.","e":"Use relative clauses to combine ideas."},{"w":"conditional","m":"条件的","p":"adj.","e":"If governments acted, ... would..."},{"w":"subjunctive","m":"虚拟的","p":"adj.","e":"Were this to happen, ... "}],"g":{"t":"五大提分句型清单","exp":"1) 倒装：Not only does remote work save money, but it also...；2) 强调句：It is motivation that determines success；3) 非限定从句：..., which means that...；4) 条件句：If governments invested more, cities would be greener；5) 虚拟/让步：Were this true, we would see... / Admittedly..., however...。每型造1句并检查正确性，考场各用1次即够——句型是调味料，不是主菜。","ex":["Not only does technology create jobs, but it also transforms them.","It is early education that shapes lifelong habits.","If cities invested in cycling, air quality would improve."]},"pr":"1) 五大句型各造1句（话题自选）。2) 把它们标进自己最近一篇作文（升级2-3处表达）。3) 朗读5遍加深记忆。","tip":"五个句型，一年之功。考场上每型露一次脸，考官的'语法广度'印象分直接拉满——这就是你52周努力的收口。"}],"sun":{"t":"第50周自检：综合语言大测","obj":"检验话题库与句型库","pr":"1) 词汇大测：全年词汇抽测100词（各阶段抽25），正确率目标85%+。2) 口头抽3个话题，每个90秒（必须用到今天复习的句型至少2个）。3) 顽固词盒复测出盒。4) 更新成长曲线表。","tip":"语言库存全部清点完毕。你会发现：一年前连be动词都陌生的你，现在在讨论政府监管和文化多样性——请为自己鼓一次掌。"}},{"w":51,"p":4,"theme":"全真模考三：考前调整","d":[{"t":"完整笔试模考","obj":"第三轮全真模拟，按考试作息","time":"3小时","v":[{"w":"rehearsal","m":"彩排；演练","p":"n.","e":"This is your final rehearsal."},{"w":"final","m":"最终的","p":"adj.","e":"The final dress rehearsal."},{"w":"complete","m":"完整的","p":"adj.","e":"Complete all four skills this week."},{"w":"evaluate","m":"评估","p":"v.","e":"Evaluate honestly, adjust calmly."},{"w":"familiar","m":"熟悉的","p":"adj.","e":"Make the whole process familiar."}],"g":{"t":"考试作息模拟","exp":"今天起完全按考试日作息：7:00起床（无论考区早晚，训练生物钟）、8:00早饭（和考试当天吃一样的量，测试自己3小时不饿不撑）、9:00开考连考三小时。下午只做轻量复盘，晚上23点前睡。连续模拟三天，让身体把'9点考试'写进本能——考试当天的从容，是练出来的生理节律。","ex":["7:00 wake up, no snooze.","8:00 breakfast: same as exam day.","9:00 - 12:00 full test. Afternoon: light review only."]},"pr":"1) 按考试作息完成第三轮笔试连考。2) 记录每科分数到成长曲线表。3) 下午轻复盘（不超过1小时），晚上早睡。","tip":"第三轮模考的分数会准得吓人——它通常就是你真实成绩的预言。无论结果如何，最后的调整空间都还握在你手里。"},{"t":"模考精析与错题本","obj":"最后一轮系统精析","time":"60分钟","v":[{"w":"eliminate","m":"消除","p":"v.","e":"Eliminate careless errors first."},{"w":"careless","m":"粗心的","p":"adj.","e":"Careless errors are the cheapest to fix."},{"w":"avoid","m":"避免","p":"v.","e":"Know your traps to avoid them."},{"w":"checklist","m":"清单","p":"n.","e":"A final checklist for exam day."},{"w":"finalize","m":"最终确定","p":"v.","e":"Finalize your exam-day checklist."}],"g":{"t":"错题模式收尾法","exp":"最后一次精析，只看'模式'不看单题：1) 马虎类错误（字数超/看错NOT/抄错）→ 全部写进考场检查清单，逐条背诵；2) 能力类错误 → 只补救'出现3次以上'的（时间不够面面俱到）；3) 一次都没错过第二遍的类型 → 考前不用再碰。做减法，不做加法：考前的心理空间比知识更重要。","ex":["Checklist: 1) Word limit 2) 'NOT' in questions 3) Capital letters 4) Transfer all answers.","Fix only recurring errors (3+ times).","Skip what you've never failed twice."]},"pr":"1) 精析第三轮模考：马虎错入清单，能力错只留高频。2) 背诵考场检查清单（今晚睡前一遍）。3) 顽固词盒最后一批复测。","tip":"到今天，你的错题本应该越来越薄。考前一周做的每道题都在'减负'：把考前要带的东西从'知识'换成'清单'。"},{"t":"口语考前模拟","obj":"题库串讲与全流程最后一遍","time":"60分钟","v":[{"w":"rehearse","m":"排练","p":"v.","e":"Rehearse your five stories one last time."},{"w":"familiar","m":"熟悉的","p":"adj.","e":"Every topic should feel familiar."},{"w":"smooth","m":"流畅的","p":"adj.","e":"Keep the delivery smooth."},{"w":"perform","m":"表演；表现","p":"v.","e":"Part 2 is a performance."},{"w":"breathe","m":"呼吸","p":"v.","e":"Breathe before you speak."}],"g":{"t":"串题总演练","exp":"把你的5大素材（1人/1事/1地/1物/1学习经历）最后过一遍：每个素材讲2分钟，边讲边想'这能套哪些卡'。然后随机抽5张新卡，每张30秒想'套哪个素材+改哪句开头'，直接2分钟开讲。目标：任何卡片抽到后，你都有'熟悉的路径'可走。Part 3别忘了四角度（政府/个人/教育/资金）万能框架。","ex":["Card: Describe a skill you learned - use 'learning English' story.","Card: A person who helped you - adapt the teacher story.","Part 3: always ask 'which angle? government / individual / education / money?'"]},"pr":"1) 五大素材各讲2分钟（录音）。2) 随机5张卡，30秒接卡+2分钟开讲。3) 回听挑出最卡的一张，明天再练一次。","tip":"口语考场的最高境界：没有生题，只有老朋友换了新衣服。你准备了52周的5个故事，明天去见考官，聊的都将是熟人。"},{"t":"全套错题与笔记回顾","obj":"重建信心，不再做新题","time":"60分钟","v":[{"w":"browse","m":"浏览","p":"v.","e":"Browse your notes, don't add."},{"w":"refresh","m":"刷新；唤起","p":"v.","e":"Refresh old memories."},{"w":"confidence","m":"信心","p":"n.","e":"Confidence is built from evidence."},{"w":"milestone","m":"里程碑","p":"n.","e":"Review your milestones."},{"w":"evidence","m":"证据","p":"n.","e":"Your growth curve is evidence."}],"g":{"t":"考前信心重建法","exp":"今天起不做任何新题（新题做错只会动摇军心）。做三件事：1) 翻错题本：重点看'曾经错过、后来对了'的题——那是你成长的证据；2) 翻词汇本：扫一眼那些'当初不认识、现在秒懂'的词；3) 看成长曲线表：第47周到现在，四科的斜率全朝上。考前焦虑的解药不是鸡汤，是数据：你已经用52周证明了自己。","ex":["Look at errors you've conquered - proof of growth.","Skim words you now know by heart.","Read your score curve: all lines point up."]},"pr":"1) 浏览错题本30分钟（只看已攻克的）。2) 浏览词汇本30分钟（只看秒懂的）。3) 看成长曲线表，写下'我的证据'一句话。","tip":"考前最怕'临阵磨刀'把自己磨慌了。现在刀已经磨了52周，今天要做的只是相信这把刀。"},{"t":"考试流程与清单","obj":"熟悉考试当天全部流程","time":"45分钟","v":[{"w":"procedure","m":"流程；手续","p":"n.","e":"Know the exam-day procedure by heart."},{"w":"identity","m":"身份；证件","p":"n.","e":"Bring your identity document."},{"w":"equipment","m":"设备","p":"n.","e":"No electronic equipment allowed."},{"w":"punctual","m":"准时的","p":"adj.","e":"Arrive early - be punctual."},{"w":"regulation","m":"规定","p":"n.","e":"Read the test center regulations."}],"g":{"t":"考试当天流程清单","exp":"笔试日：提前1小时到考场 → 存包（手机静音上交）→ 刷指纹/拍照验证 → 候考 → 入场（只带身份证和透明瓶装水，去掉标签）→ 听力9:00开始。口试日：提前30分钟到 → 候考室等待 → 单独考房11-14分钟。物品清单：身份证件、准考证、水（无标签）、午餐安排、路线图（提前踩点）。今晚把清单打印出来放门口。","ex":["ID card + confirmation letter","Water bottle without label","Arrive 60 minutes before the written test","Speaking test: arrive 30 minutes early"]},"pr":"1) 写自己的考试日清单（时间/物品/路线三栏）。2) 核对证件有效期。3) 查好去考场的路线和时间（计划提前1小时）。","tip":"流程熟悉到'自动化'，紧张就没有空子可钻。考场上唯一该想的只有题——其他的，今天全解决掉。"}],"sun":{"t":"第51周自检：心态与作息调整","obj":"完成最后的作息与心理准备","pr":"1) 复盘本周三轮状态：作息跟上了吗？连考不慌了吗？2) 口语5素材最后一遍串讲。3) 检查清单：证件/路线/物品，全部打勾。4) 本周23:00前睡，连续7天。","tip":"最后的敌人不是英语，是心态。你的水平已经写定了，这周的任务是不让紧张偷走它。规律作息，就是最好的镇静剂。"}},{"w":52,"p":4,"theme":"考前一周：状态巅峰","d":[{"t":"轻量复习·词汇速览","obj":"激活记忆，不学新知","time":"30分钟","v":[{"w":"glance","m":"浏览；扫一眼","p":"v./n.","e":"Take a glance at your word lists."},{"w":"recall","m":"回想；回忆","p":"v.","e":"Recall, don't relearn."},{"w":"activate","m":"激活","p":"v.","e":"Activate passive vocabulary."},{"w":"swift","m":"迅速的","p":"adj.","e":"A swift review works best."},{"w":"memory","m":"记忆","p":"n.","e":"Trust your year-long memory."}],"g":{"t":"考前复习三原则","exp":"原则一：只激活，不新增——新知识进不了短期记忆还挤占空间。原则二：每次不超过30分钟——大脑考前需要'轻负荷'。原则三：优先看'马上要用的'——口语素材、写作模板、听力替换词、阅读检查清单，按考试顺序过。把厚厚的笔记留在书架上，只带'一页纸'进考场。","ex":["Day 1-2: vocabulary glance (30 min only)","Day 3: speaking stories","Day 4: listening ears - no new drills."]},"pr":"1) 词汇本速览30分钟（只看加粗词）。2) 口头自测：随机10词秒答。3) 今天的英语输入到此为止，去做点开心的事。","tip":"考前一周的复习像给植物浇水——浇太多会淹死。你这一年浇的已经够多了，现在只需要阳光。"},{"t":"轻量复习·语法与错题","obj":"过一遍高频语法点","time":"30分钟","v":[{"w":"skim","m":"略读","p":"v.","e":"Skim your grammar notes."},{"w":"revise","m":"温习","p":"v.","e":"Revise the five score-boosting patterns."},{"w":"fundamental","m":"基本的","p":"adj.","e":"Fundamentals win points."},{"w":"solidify","m":"巩固","p":"v.","e":"Solidify, don't expand."},{"w":"ready","m":"准备好的","p":"adj.","e":"You are more ready than you feel."}],"g":{"t":"语法速览清单","exp":"只过这五样：1) 五大句型（倒装/强调/非限定从句/条件/让步）各念1遍例句；2) 写作高频错：三单s、时态一致、government无复数；3) 听力拼写高危词：accommodation/environment/necessary/receive；4) 阅读字数军规：NO MORE THAN THREE WORDS；5) 口语开头万能句：Well, that's an interesting question... 过完就合上，别再翻。","ex":["Say aloud: 'Not only does it save money...'","Check: 'The government has', not 'have'.","Spelling drill: a-c-c-o-m-m-o-d-a-t-i-o-n."]},"pr":"1) 五大句型例句各朗读2遍。2) 高危拼写词默写一遍。3) 合上所有材料，今天到此为止。","tip":"语法复习的终点是'肌肉'不是'脑子'——读出声，让嘴巴记住，考场才调得动。"},{"t":"口语热身日","obj":"保持开口状态，不上强度","time":"30分钟","v":[{"w":"warm","m":"热身的；温暖的","p":"adj.","e":"Keep your speaking muscles warm."},{"w":"vocal","m":"嗓音的","p":"adj.","e":"Do gentle vocal exercises."},{"w":"articulate","m":"清晰地说","p":"v.","e":"Articulate clearly, not fast."},{"w":"express","m":"表达","p":"v.","e":"Express yourself calmly."},{"w":"relax","m":"放松","p":"v.","e":"Relax - you know these stories."}],"g":{"t":"口语考前热身","exp":"每天保持15分钟'嘴部热身'：1) 对镜子说英文（任何话题，重在开口状态）；2) 5大素材各讲1分钟（不求完美，求顺）；3) 念3句五大句型（让高级句型挂在嘴边）。不练新话题、不录音自评、不纠音——这周口语的KPI只有一个：开口不生涩。","ex":["Mirror talk: describe your day in English for 5 minutes.","Five stories, one minute each.","Read aloud: 'Not only does it save money, but...'"]},"pr":"1) 镜子英文自述5分钟。2) 5大素材各1分钟。3) 念3个句型例句，语速放慢，吐字清晰。","tip":"口语是身体技能，和跑步一样讲'状态'。这周的任务不是变强，是保持手感——别让嘴巴在考前一周'着凉'。"},{"t":"听力耳感保持","obj":"每天30分钟，维持耳朵状态","time":"30分钟","v":[{"w":"maintain","m":"保持","p":"v.","e":"Maintain your listening fitness."},{"w":"expose","m":"使接触","p":"v.","e":"Expose your ears to English daily."},{"w":"familiar","m":"熟悉的","p":"adj.","e":"Keep the exam voices familiar."},{"w":"accent","m":"口音","p":"n.","e":"Stick to British accents this week."},{"w":"tune","m":"调音；调整","p":"v.","e":"Tune your ears like an instrument."}],"g":{"t":"耳感保持法","exp":"每天30分钟'背景输入'：BBC纪录片、TED演讲（英音优先），只求'耳熟'不求精听。不做题、不精听、不查词——这周的听力训练量降到最低，只为保持耳朵对英语的'灵敏度'。可以边做家务边听。如果听不太懂也别慌：状态是波浪形的，考场上 adrenaline（考试兴奋）会自动帮你调到峰值。","ex":["30 min BBC documentary while having breakfast.","No questions, no transcripts, no dictionary.","Just keep the English sounds flowing daily."]},"pr":"1) 30分钟英音材料（吃饭/散步时听）。2) 不做题不查词。3) 明天同一时间继续。","tip":"耳朵和肌肉一样会'冷'。每天30分钟保温，考场上打开耳机那一刻，你会感谢这份熟悉感。"},{"t":"考前清单与踩点","obj":"完成全部考前准备","time":"45分钟","v":[{"w":"passport","m":"护照","p":"n.","e":"Check your passport is valid."},{"w":"route","m":"路线","p":"n.","e":"Plan your route with a buffer."},{"w":"confirm","m":"确认","p":"v.","e":"Confirm your test date and venue."},{"w":"prepare","m":"准备","p":"v.","e":"Prepare everything the night before."},{"w":"checklist","m":"清单","p":"n.","e":"The final checklist - all green."}],"g":{"t":"考前48小时清单","exp":"证件：身份证件原件（核对有效期）+ 准考证确认信打印件。路线：考场踩点一次，记录路上时间×1.5（考试日交通）；设3个闹钟。物品：透明瓶装水（撕标签）、手表摘掉（考场有钟）、手机准备上交。身体：今晚开始清淡饮食，23点前睡；考试日早饭照常（别尝试新食物）。心理：把'考试日流程'在心里过一遍电影，每个环节都熟悉得像回家。","ex":["ID valid? Confirmation letter printed?","Route tested - allow 1.5x travel time.","Three alarms set. Breakfast planned."]},"pr":"1) 逐项打钩完成清单。2) 去考场踩点一次。3) 把考试当天的衣服、物品摆在门口。","tip":"把所有'万一'在今天消灭。考场上唯一允许发生的意外是——你超常发挥。"}],"sun":{"t":"考前一天：轻装上阵","obj":"完成52周旅程，明天去拿6.5","pr":"1) 上午：笔记速览30分钟封顶（口语素材+检查清单最后过一遍）。2) 下午：散步30分钟，看看这一年写满的错题本和成长曲线表。3) 晚上：准备好证件物品，22:30上床，睡满8小时。4) 明天：提前1小时到考场，深呼吸，微笑进场。","tip":"52周，364天，1300多个单词，260多次晨读，37篇改过的作文，无数次按下录音键——这些都已长在你身上。明天你只需要做一件事：把这一年的自己，正常发挥出来。Good luck - you've earned it."}}];
